+
+/** Record a target-specific relation event for every long-lived tracking factory. */
+export function setPairTrackingEvent(
+    world: World,
+    entity: Entity,
+    trait: Trait,
+    target: Entity,
+    type: 'add' | 'remove' | 'change'
+) {
+    const ctx = world[$internal];
+    const key = `${trait.id}:${entity}:${target}`;
+
+    for (const [id, events] of ctx.pairTrackingEvents) {
+        const baseline = ctx.pairTrackingSnapshots.get(id)!;
+        if (type === 'change') {
+            events.set(key, type);
+        } else if (type === 'add') {
+            baseline.has(key) ? events.delete(key) : events.set(key, type);
+        } else {
+            baseline.has(key) ? events.set(key, type) : events.delete(key);
+        }
+    }
+
+    const data = getTraitInstance(ctx.traitInstances, trait);
+    if (!data) return;
+    for (const query of data.trackingQueries) {
+        if (!query.trackingGroups.some((group) => group.relationPairs.length)) continue;
+        if (matchesPairTracking(world, query, entity)) query.add(entity);
+        else query.remove(world, entity);
+    }
+}
+
+function matchesPairTracking(world: World, query: import('../types').QueryInstance, entity: Entity) {
+    if (!checkQueryWithRelations(world, query, entity)) return false;
+    const eventsById = world[$internal].pairTrackingEvents;
+    for (const group of query.trackingGroups) {
+        let ordinaryMatches = true;
+        for (let genId = 0; genId < group.bitmasks.length; genId++) {
+            const mask = group.bitmasks[genId];
+            if (!mask) continue;
+            const tracker = group.trackers[genId]?.[getEntityId(entity)] ?? 0;
+            if ((tracker & mask) !== mask) ordinaryMatches = false;
+        }
+        const events = eventsById.get(group.id);
+        const pairMatches = group.relationPairs.map((pair) => {
+            const pairCtx = pair[$internal];
+            const relationId = pairCtx.relation[$internal].trait.id;
+            for (const [key, event] of events ?? []) {
+                const [eventRelationId, eventEntity, eventTarget] = key.split(':');
+                if (+eventRelationId !== relationId || +eventEntity !== entity) continue;
+                if (pairCtx.target !== '*' && +eventTarget !== pairCtx.target) continue;
+                if (event === group.type) return true;
+            }
+            return false;
+        });
+        const matches = group.logic === 'or'
+            ? ordinaryMatches || pairMatches.some(Boolean)
+            : ordinaryMatches && pairMatches.every(Boolean);
+        if (!matches) return false;
+    }
+    return true;
+}
